#include <cmath>
#include <algorithm>
extern "C" void render(const double *pts, int n, float *img,int size, double mmpp) {
 double rx=pts[0],ry=pts[1],w=0,d=0,theta=atan2(pts[4]-pts[1],pts[3]-pts[0]);
 for(int i=0;i<n;i++) {
  double x=pts[3*i], y=pts[3*i+1], z=pts[3*i+2];
  double zz=std::max(0.,std::min(15.,z));
  w=.02*w+.98*(z>0?std::max(0.,1.187*zz-.3):0.);
  d=.02*d+.98*(z>0?1.38+1.075*zz:0.);
  double O=z>0?std::max(0.,11.15-.0967*(zz-10.91)*(zz-10.91)):0;
  double vx=x-rx,vy=y-ry,L=hypot(vx,vy),o=std::min(O,L);
  if(L>(z>0?1.:.1)) theta=atan2(vy,vx);
  if(L>0){rx=x-vx*o/L;ry=y-vy*o/L;}
  if(z<=0||w<.001) continue;
  double ex=cos(theta),ey=sin(theta),nx=-ey,ny=ex, hw=w/2;
  double xmin=std::min(rx,rx-d*ex)-fabs(hw*nx),xmax=std::max(rx,rx-d*ex)+fabs(hw*nx);
  double ymin=std::min(ry,ry-d*ey)-fabs(hw*ny),ymax=std::max(ry,ry-d*ey)+fabs(hw*ny);
  int c0=std::max(0,(int)floor(xmin/mmpp)-2),c1=std::min(size-1,(int)ceil(xmax/mmpp)+2);
  int r0=std::max(0,(int)floor(ymin/mmpp)-2),r1=std::min(size-1,(int)ceil(ymax/mmpp)+2);
  for(int r=r0;r<=r1;r++)for(int c=c0;c<=c1;c++){
   double qx=(c+.5)*mmpp-rx,qy=(r+.5)*mmpp-ry;
   double s=-(qx*ex+qy*ey),t=qx*nx+qy*ny;
   double f=d*(1-4*t*t/(w*w))-s,g=sqrt(1+pow(8*d*t/(w*w),2));
   float a=std::max(0.,std::min(1.,std::min(s,f/g)/mmpp+.5));
   img[r*size+c]=std::max(img[r*size+c],a);
  }
 }
}
