target=cv2.imread('/app/target.png',0)<100
t=cv2.resize(target.astype(np.float32),(S,S),interpolation=cv2.INTER_AREA)
outdist=cv2.distanceTransform((t<.5).astype(np.uint8),cv2.DIST_L2,5)*MM/S
