[[559,468,.1],[583,490,5.1],[617,488,7],[658,477,7],[701,468,7],[705,466,.1]],
[[524,552,.1],[532,585,3.5],[553,596,4.2],[598,581,5.3],[654,555,7.5],[700,542,7.9],[702,540,.1]],
[[540,605,.1],[560,641,6],[573,683,7.5],[579,733,9],[603,752,6],[607,755,.1]],
[[563,643,.1],[599,653,4.5],[639,647,5],[684,630,6.8],[735,617,10],[751,634,9],[721,675,8],[688,715,6.5],[654,777,.1]],
[[582,743,.1],[621,739,8],[660,737,8],[704,741,8.6],[721,748,7],[724,751,.1]],
]
paths=[np.array(a,float)*[P,P,1] for a in raw]

def samples(nodes,ds=.18):
 # interpolate using arc length in three dimensions
 lengths=np.linalg.norm(np.diff(nodes,axis=0),axis=1)
 tau=np.r_[0,np.cumsum(np.maximum(lengths,.1))]
 u=np.linspace(0,tau[-1],int(tau[-1]/ds)+1)
 a=PchipInterpolator(tau,nodes,axis=0)(u)
 # settle at starting surface and finish lifting, no extra horizontal stroke
 a=np.vstack([np.r_[nodes[0,:2],0],a,np.r_[nodes[-1,:2],0]])
 return np.ascontiguousarray(a,dtype=np.float64)
def render(nodes):
 a=samples(nodes); out=np.zeros((S,S),np.float32)
 lib.render(a.ctypes.data,len(a),out.ctypes.data,S,MM/S)
 return out

def save(paths,name='fit'):
 np.savez('/app/output/'+name+'.npz',**{str(i):a for i,a in enumerate(paths)})
 out=np.maximum.reduce([render(a) for a in paths]);vis=np.full((S,S,3),250,np.uint8)
 vis[t>.5]=[180,180,180];vis[out>.5]=[0,0,0];vis[(out>.5)&(t<.5)]=[70,70,240];vis[(out<.5)&(t>.5)]=[220,120,40]
 cv2.imwrite('/app/output/'+name+'.png',vis)
 b=out>.5;tt=t>.5
 print(name,'IoU',np.sum(b&tt)/np.sum(b|tt),'recall',np.sum(b&tt)/np.sum(tt),'stray',np.sum(b&(outdist>1))/np.sum(tt),flush=True)

if __name__=='__main__':
 import sys
 if len(sys.argv)>1:
  inp=np.load(sys.argv[1]);paths=[inp[str(i)].copy() for i in range(9)]
 save(paths,'initial')
 rasters=[render(a) for a in paths]
 for loop in range(5):
  for i in range(9):
   other=np.maximum.reduce([a for j,a in enumerate(rasters) if i!=j]);base=paths[i].copy(); shape=base.shape
   # constrain initial light-contact/end nodes, broad limits on the lengthwise skeleton
   bounds=[]
   for j,row in enumerate(base):
    bounds.extend([(row[0]-5,row[0]+5),(row[1]-5,row[1]+5),(.05,13)])
   calls=[0];start=time.time()
   def loss(v):
    nodes=v.reshape(shape);a=render(nodes);pred=np.maximum(a,other)
    diff=pred-t
    err=np.sum(diff*diff*weight)/np.sum(t)
    # small elastic regularizer keeps stroke shape smooth and prevents detours
    err+=.00008*np.sum((nodes[:,:2]-base[:,:2])**2)
    calls[0]+=1
    return err
   res=minimize(loss,base.ravel(),method='Powell',bounds=bounds,options={'maxiter':9,'ftol':1e-5,'xtol':.025})
   paths[i]=res.x.reshape(shape);rasters[i]=render(paths[i])
   print(loop,i,round(res.fun,5),calls[0],round(time.time()-start,1),flush=True)
   save(paths,'fit')
  save(paths,'loop'+str(loop))
